function test(sink) {
  try {
    var supported = !!window.trustedTypes;
    if (sink === 'trustedTypes') {
      addInfo(sink, supported ? 'available' : 'not exposed');
      return;
    }
    var div = document.createElement('div');
    var result = 'not exercised';
    if (sink === 'innerHTML') {
      div.innerHTML = '<span data-probe="1">ok</span>';
      result = div.firstElementChild ? div.firstElementChild.tagName : 'empty';
    }
    if (sink === 'outerHTML') {
      div.outerHTML = '<section data-probe="1"></section>';
      result = 'accepted';
    }
    if (sink === 'insertAdjacentHTML') {
      div.insertAdjacentHTML('beforeend', '<b data-probe="1">ok</b>');
      result = div.children.length + ' child';
    }
    if (sink === 'Range.createContextualFragment') {
      result = document.createRange().createContextualFragment('<i data-probe="1">ok</i>').children.length + ' child';
    }
    if (sink === 'DOMParser.parseFromString') {
      result = new DOMParser().parseFromString('<p>ok</p>', 'text/html').body.children.length + ' body child';
    }
    if (sink === 'script.src') {
      var script = document.createElement('script');
      script.src = 'about:blank';
      result = script.src;
    }
    addInfo(sink, JSON.stringify({ trustedTypes: supported, result: result }));
  } catch (error) {
    addError(sink, error.name + ': ' + error.message);
  }
}

function test(feature) {
  var target = document.createElement('div');
  var observed = 'missing';
  try {
    if (feature === 'Sanitizer') observed = typeof window.Sanitizer;
    if (feature === 'Element.setHTML') observed = typeof target.setHTML;
    if (feature === 'Element.setHTMLUnsafe') observed = typeof target.setHTMLUnsafe;
    if (feature === 'Document.parseHTML') observed = typeof Document.parseHTML;
    if (feature === 'Document.parseHTMLUnsafe') observed = typeof Document.parseHTMLUnsafe;
    if (feature === 'ShadowRoot.setHTMLUnsafe') observed = typeof Element.prototype.attachShadow === 'function' ? typeof target.attachShadow({ mode: 'open' }).setHTMLUnsafe : 'no shadow root';
    addInfo(feature, observed);
  } catch (error) {
    addError(feature, error.name + ': ' + error.message);
  }
}

function test(name) {
  var host = document.createElement('form');
  host.id = name;
  host.name = name;
  var input = document.createElement('input');
  input.name = name;
  host.appendChild(input);
  document.body.appendChild(host);
  try {
    var docValue = document[name];
    var winValue = window[name];
    addInfo(name, JSON.stringify({ documentType: Object.prototype.toString.call(docValue), windowType: Object.prototype.toString.call(winValue), windowOwn: Object.prototype.hasOwnProperty.call(window, name) }));
  } catch (error) {
    addError(name, error.name + ': ' + error.message);
  } finally {
    host.remove();
  }
}

function test(expression) {
  try {
    var value = Function('return ' + expression)();
    var relation = value === window ? 'same window' : Object.prototype.toString.call(value);
    addInfo(expression, relation);
  } catch (error) {
    addError(expression, error.name + ': ' + error.message);
  }
}

function test(field) {
  try {
    var event = new MessageEvent('message', { data: 'payload', origin: location.origin, source: window });
    var before = event[field];
    var writable = true;
    try { event[field] = 'dom-lab'; } catch (error) { writable = false; }
    var descriptor = Object.getOwnPropertyDescriptor(MessageEvent.prototype, field) || Object.getOwnPropertyDescriptor(Event.prototype, field);
    addInfo(field, JSON.stringify({ before: String(before), after: String(event[field]), writable: writable, configurable: !!(descriptor && descriptor.configurable) }));
  } catch (error) {
    addError(field, error.name + ': ' + error.message);
  }
}

