    if (feature === 'SharedArrayBuffer') value = typeof SharedArrayBuffer;
    if (feature === 'performance.measureUserAgentSpecificMemory') value = typeof performance.measureUserAgentSpecificMemory;
    if (feature === 'Atomics.waitAsync') value = typeof Atomics.waitAsync;
    if (feature === 'credentialless') value = 'credentialless' in HTMLIFrameElement.prototype;
    addInfo(feature, String(value));
