async function test(api) {
  try {
    if (api === 'localStorage' || api === 'sessionStorage') {
      window[api].setItem('__dom_lab_probe__', '1');
      window[api].removeItem('__dom_lab_probe__');
      addSuccess(api, 'read/write available');
      return;
    }
    if (api === 'document.hasStorageAccess') {
      addInfo(api, typeof document.hasStorageAccess === 'function' ? String(await document.hasStorageAccess()) : 'missing');
      return;
    }
    addInfo(api, api.split('.').reduce(function(obj, part) { return obj && obj[part]; }, window) ? 'exposed' : 'missing');
  } catch (error) {
    addInfo(api, 'blocked: ' + error.name + ': ' + error.message);
  }
}

function test(name) {
  try {
    var before = document.cookie;
    document.cookie = name + '=1; SameSite=Lax; path=/';
    var after = document.cookie;
    document.cookie = name + '=; expires=Thu, 01 Jan 1970 00:00:00 GMT; path=/';
    addInfo(name, JSON.stringify({ beforeLength: before.length, accepted: after.indexOf(name + '=') !== -1, afterLength: after.length }));
  } catch (error) {
    addInfo(name, 'blocked: ' + error.name + ': ' + error.message);
  }
}

