function test(rule) {
  try {
    var sheet = new CSSStyleSheet();
    sheet.replaceSync(rule);
    addInfo(rule, JSON.stringify({ rules: sheet.cssRules.length, first: sheet.cssRules[0] ? sheet.cssRules[0].constructor.name : 'none' }));
  } catch (error) {
    addError(rule, error.name + ': ' + error.message);
  }
}

function test(caseName) {
  var carrier = Object.create({ method: 'POST', origin: 'https://polluted.example', transfer: [] });
  try {
    var result = 'not applicable';
    if (caseName === 'RequestInit.method') result = new Request('about:blank', carrier).method;
    if (caseName === 'MessageEventInit.origin') result = new MessageEvent('message', carrier).origin;
    if (caseName === 'DOMParser options') result = new DOMParser().parseFromString('<p>x</p>', 'text/html').body.textContent;
    if (caseName === 'structuredClone transfer') result = typeof structuredClone === 'function' ? Object.prototype.toString.call(structuredClone({ ok: true }, carrier)) : 'missing';
    if (caseName === 'URLSearchParams object') result = new URLSearchParams(Object.create({ a: 'polluted' })).toString() || 'empty';
    addInfo(caseName, result);
  } catch (error) {
    addError(caseName, error.name + ': ' + error.message);
  }
}

function test(kind) {
  try {
    var value;
    if (kind === 'URL') value = new URL('https://example.test/a');
    if (kind === 'DOMException') value = new DOMException('x', 'DataError');
    if (kind === 'Error') value = new Error('x');
    if (kind === 'ReadableStream') value = new ReadableStream();
    if (kind === 'AbortSignal') value = new AbortController().signal;
    if (kind === 'CryptoKey placeholder') value = { note: 'requires async crypto.subtle key generation' };
    if (kind === 'HTMLElement') value = document.createElement('div');
    var clone = structuredClone(value);
    addInfo(kind, Object.prototype.toString.call(clone));
  } catch (error) {
    addError(kind, error.name + ': ' + error.message);
  }
}

function test(hex) {
  try {
    var bytes = new Uint8Array(hex.match(/../g).map(function(part) { return parseInt(part, 16); }));
    addInfo(hex, JSON.stringify({ wasm: typeof WebAssembly, valid: WebAssembly.validate(bytes) }));
  } catch (error) {
    addError(hex, error.name + ': ' + error.message);
  }
}

