function test(feature) {
  try {
    var result;
    if (feature === 'HTMLScriptElement.supports importmap') result = !!(HTMLScriptElement.supports && HTMLScriptElement.supports('importmap'));
    if (feature === 'HTMLScriptElement.supports speculationrules') result = !!(HTMLScriptElement.supports && HTMLScriptElement.supports('speculationrules'));
    if (feature === 'modulepreload link') { var link = document.createElement('link'); link.rel = 'modulepreload'; result = link.relList && link.relList.supports ? link.relList.supports('modulepreload') : link.rel; }
    if (feature === 'nomodule') { var script = document.createElement('script'); result = 'noModule' in script; }
    if (feature === 'import.meta unavailable') result = 'classic script probe';
    addInfo(feature, String(result));
